'use strict';
let serverMode=false,principal=null,otpChallenge='',requestBusy=false;
async function api(url,data){const r=await fetch(url,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,credentials:'same-origin'});const j=await r.json();if(!r.ok)throw Error(j.error||'تعذر تنفيذ الطلب.');return j;}
function acceptServer(j){db=j.db;principal=j.principal;signedAccount=principal.account||db.accounts.find(a=>a.shop===principal.shop)?.id||db.accounts[0]?.id;role={owner:'owner',employee:'staff',customer:'client',admin:'admin'}[principal.kind];if(role==='staff'){staffEmployee=principal.employee;view='scan';}if(role==='client'){clientStage='card';db.member=principal.member;}save=()=>{};}
async function serverCommand(data,{redraw=true}={}){if(requestBusy)throw Error('انتظر اكتمال العملية الحالية.');requestBusy=true;try{const j=await api('/api/command',{...data,shop:data.shop||db.shop});const priorView=view,priorRole=role;acceptServer(j);if(principal.kind==='admin'){role=priorRole;view=priorView;}else if(principal.kind==='owner')view=priorView;if(redraw)render();return j.result;}finally{requestBusy=false;}}
const decoratedRender=render;
render=function(){decoratedRender();if(!serverMode)return;document.querySelector('[data-action="demo-admin"]')?.remove();document.querySelectorAll('.demo-label').forEach(el=>el.textContent='رِجعة · مساحة آمنة');document.querySelectorAll('.role-switch').forEach(el=>el.remove());document.querySelectorAll('.reset').forEach(el=>el.remove());document.querySelectorAll('[data-action="simulate-scan"],#staff-member').forEach(el=>el.remove());document.querySelector('#staff-employee')?.setAttribute('disabled','');document.querySelectorAll('.auth-layout .notice').forEach(el=>{if(el.textContent.includes('للتجربة:'))el.remove();if(el.textContent.includes('رمز التجربة:'))el.textContent='أدخل رمز التحقق الذي وصلك عبر رسالة نصية.';});document.querySelectorAll('.public-footer span:last-child').forEach(el=>el.textContent='رِجعة · برنامج ولاء نشاطك');if(!publicPage){const bar=document.querySelector('.topbar');if(bar){const exit=document.createElement('button');exit.className='btn quiet small';exit.textContent='تسجيل الخروج';exit.dataset.action='server-logout';bar.append(exit);}}if(publicPage==='login')document.querySelector('.auth-layout>section>p').textContent='صاحب النشاط يدخل إلى لوحته، والموظف يدخل إلى شاشة تسجيل الزيارات برقم جواله.';};
const demoScan=processScan;
processScan=async function(code){if(!serverMode)return demoScan(code);try{const result=await serverCommand({action:staffMode,code,requestId:crypto.randomUUID()},{redraw:false});lastTx={...result,shop:shop().id,undone:false};if(stream){scannerLock=true;document.querySelector('#scan-status').textContent='تم تسجيل العملية.';}else render();toast(staffMode==='stamp'?'تمت إضافة الختم.':'تم صرف المكافأة.');}catch(e){toast(e.message);}};
window.addEventListener('click',async e=>{if(!serverMode)return;const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;const handled=new Set(['save-card','toggle-employee','confirm-activation','confirm-suspend','create-token','revoke-token','undo','manual-scan','server-logout','role','reset','confirm-reset','add-shop','toggle-shop','demo-admin']);if(!handled.has(a))return;e.preventDefault();e.stopImmediatePropagation();try{if(['role','reset','confirm-reset','add-shop','toggle-shop','demo-admin'].includes(a))throw Error('غير متاح لهذا الحساب.');if(a==='server-logout'){await api('/api/auth/logout',{});principal=null;publicPage='login';loginStep='phone';render();return;}if(a==='manual-scan'){await processScan(document.querySelector('#manual-code').value);return;}if(a==='save-card')await serverCommand({action:'save-card',card:draft});if(a==='toggle-employee')await serverCommand({action:'toggle-employee',id:b.dataset.id});if(a==='confirm-activation'){await serverCommand({action:'activate',id:b.dataset.id,period:b.dataset.period,paymentApproved:true});document.querySelector('#modal').close();}if(a==='confirm-suspend'){await serverCommand({action:'suspend',id:b.dataset.id});document.querySelector('#modal').close();}if(a==='create-token'){if(!document.querySelector('#payment-approved').checked)throw Error('اعتمد الدفع أولًا.');const result=await serverCommand({action:'issue-token',id:b.dataset.id,period:document.querySelector('#token-period').value,paymentApproved:true});modal('التوكن جاهز',`<p>يظهر التوكن كاملًا مرة واحدة. احتفظ به وأرسله لصاحب الحساب.</p><input id="issued-token" class="input mt" dir="ltr" readonly value="${esc(result.code)}">`,'<button class="btn primary" data-action="copy-token">نسخ التوكن</button>');}if(a==='revoke-token')await serverCommand({action:'revoke-token',id:b.dataset.id});if(a==='undo'){await serverCommand({action:'undo',code:lastTx.member,transaction:lastTx.transaction,requestId:crypto.randomUUID()});lastTx=null;render();}toast('تم تنفيذ الإجراء.');}catch(error){toast(error.message);}},true);
window.addEventListener('submit',async e=>{if(!serverMode)return;const f=e.target,d=new FormData(f);if(typeof emailLoginMode!=='undefined'&&emailLoginMode&&['employee-form','join-form','otp-form'].includes(f.id))return;if(!['phone-login','phone-login-verify','employee-form','token-redeem','join-form','otp-form'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();try{if(f.id==='phone-login'){const kind=/^\/admin\/?$/i.test(location.pathname)?'admin':loginType==='employee'?'employee':'owner';loginPhone=normalizePhone(d.get('phone'));if(!loginPhone)throw Error('رقم الجوال غير صحيح.');loginName=String(d.get('name')||'').trim();loginBusiness=String(d.get('business')||'').trim();const j=await api('/api/auth/request',{kind,phone:loginPhone,name:loginName,business:loginBusiness,register:newBusiness});otpChallenge=j.challenge;loginStep='otp';render();}else if(f.id==='phone-login-verify'){const j=await api('/api/auth/verify',{challenge:otpChallenge,code:d.get('otp')});acceptServer(j);publicPage='';view=role==='staff'?'scan':role==='admin'?'accounts':'overview';render();}else if(f.id==='employee-form'){await serverCommand({action:'add-employee',name:d.get('name'),phone:d.get('phone')});document.querySelector('#modal').close();}else if(f.id==='token-redeem'){await serverCommand({action:'redeem-token',code:d.get('token')});toast('تم تفعيل الاشتراك.');}else if(f.id==='join-form'){clientPhone=normalizePhone(d.get('phone'));clientName=String(d.get('name')||'');const j=await api('/api/auth/request',{kind:'customer',phone:clientPhone,name:clientName,shop:shop().id});otpChallenge=j.challenge;clientStage='otp';render();}else if(f.id==='otp-form'){const j=await api('/api/auth/verify',{challenge:otpChallenge,code:d.get('otp')});acceptServer(j);publicPage='';render();}}catch(error){const el=document.querySelector('#login-error,#token-error,#employee-error,#join-error,#otp-error');if(el)el.textContent=error.message;else toast(error.message);}},true);
(async()=>{try{const r=await fetch('/api/config');if(!r.ok){if(window.RIJAA_DEPLOYED)throw Error('تعذر الاتصال بالخدمة.');return;}const c=await r.json();if(c.mode!=='server')return;serverMode=true;document.documentElement.classList.add('ready');save=()=>{};db={shops:[],accounts:[],tokens:[],adminLogs:[],settings:{whatsapp:c.whatsapp},shop:'',member:''};const requestedShop=new URLSearchParams(location.search).get('join');if(requestedShop){const j=await api('/api/public/shop?id='+encodeURIComponent(requestedShop));db=j.db;role='client';clientStage='phone';publicPage='';render();return;}try{acceptServer(await api('/api/state'));publicPage='';view=role==='staff'?'scan':role==='admin'?'accounts':'overview';}catch{publicPage=/^\/(admin|login)\/?$/i.test(location.pathname)?'login':'home';}render();}catch(e){if(window.RIJAA_DEPLOYED){document.querySelector('#app').innerHTML='<main class=auth-layout><section><h1>تعذر الاتصال بالخدمة</h1><p>أعد تحميل الصفحة بعد قليل.</p></section></main>';document.documentElement.classList.add('ready');}}})();
